/* Modèle de Gordon : prix d'une action P = D1/(r-g) en fonction de g */
(function () {
  var svg = document.getElementById("eq-chart");
  if (!svg) return;
  function v(id){ return parseFloat(document.getElementById(id).value); }
  function setT(id,t){ var e=document.getElementById(id); if(e) e.textContent=t; }
  function al(){ return document.body.getAttribute("data-active-lang")||"fr"; }

  function draw(){
    var D=v("eq-d"), r=v("eq-r")/100, g=v("eq-g")/100;
    setT("eq-d-o", D.toFixed(1)); setT("eq-r-o",(r*100).toFixed(1)+"%"); setT("eq-g-o",(g*100).toFixed(1)+"%");
    var price = (g<r) ? D/(r-g) : NaN;
    if (isFinite(price)) { setT("eq-price", price.toFixed(2)+" €"); setT("eq-yield",(D/price*100).toFixed(2)+"%"); }
    else { setT("eq-price", (al()==="en"?"undefined (g ≥ r)":(al()==="nl"?"ongedefinieerd (g ≥ r)":"non défini (g ≥ r)"))); setT("eq-yield","—"); }

    var W=520,H=260,L=44,R=14,T=14,B=32, pw=W-L-R, ph=H-T-B;
    var gmax = r - 0.003;                 // g juste en dessous de r
    var xmin=0, xmax=Math.max(0.12, r+0.02);
    // prix max pour l'échelle : cap au prix à g = r-1%
    var pcap = D/Math.max(0.01, (r-(r-0.01)));  // = D/0.01
    var ymax = Math.min(D/0.01, D/(r-Math.min(g, r-0.005))*1.3);
    ymax = Math.max(ymax, D/(r- (r-0.02)) ); // au moins jusqu'à g=r-2%
    if (!isFinite(ymax) || ymax<=0) ymax = D/0.02;
    ymax = Math.min(ymax, D/0.005);       // plafond dur
    function px(x){ return L + (x-xmin)/(xmax-xmin)*pw; }
    function py(y){ return T + (1-Math.min(y,ymax)/ymax)*ph; }

    var g2="";
    // axes
    g2+='<line class="axis" x1="'+L+'" y1="'+T+'" x2="'+L+'" y2="'+(T+ph)+'"/>';
    g2+='<line class="axis" x1="'+L+'" y1="'+(T+ph)+'" x2="'+(L+pw)+'" y2="'+(T+ph)+'"/>';
    // courbe P(g) pour g de 0 à gmax
    var N=120, d="";
    for (var i=0;i<=N;i++){
      var gg = xmin + (gmax-xmin)*i/N;
      var pp = D/(r-gg);
      if (pp>ymax*1.05) { d += " M "+px(gg).toFixed(1)+","+py(ymax).toFixed(1); continue; }
      d += (d===""?"M ":" L ")+px(gg).toFixed(1)+","+py(pp).toFixed(1);
    }
    g2+='<path d="'+d+'" fill="none" stroke="var(--teal)" stroke-width="2.6"/>';
    // asymptote g=r
    g2+='<line x1="'+px(r).toFixed(1)+'" y1="'+T+'" x2="'+px(r).toFixed(1)+'" y2="'+(T+ph)+'" stroke="var(--crimson)" stroke-width="1.4" stroke-dasharray="4 3"/>';
    g2+='<text class="lab" x="'+(px(r)-4).toFixed(1)+'" y="'+(T+12)+'" text-anchor="end" fill="var(--crimson)">g = r</text>';
    // point courant
    if (g<r && isFinite(price)){
      g2+='<circle cx="'+px(g).toFixed(1)+'" cy="'+py(price).toFixed(1)+'" r="4" fill="var(--ink)"/>';
      g2+='<line class="axis" x1="'+px(g).toFixed(1)+'" y1="'+py(price).toFixed(1)+'" x2="'+px(g).toFixed(1)+'" y2="'+(T+ph)+'" stroke-dasharray="3 3" stroke-width="1"/>';
    }
    // ticks x
    g2+='<text class="tick" x="'+L+'" y="'+(H-16)+'" text-anchor="start">0%</text>';
    g2+='<text class="tick" x="'+(L+pw)+'" y="'+(H-16)+'" text-anchor="end">'+(xmax*100).toFixed(0)+'%</text>';
    // ticks y
    g2+='<text class="tick" x="'+(L-6)+'" y="'+(py(ymax)+4).toFixed(1)+'" text-anchor="end">'+ymax.toFixed(0)+'</text>';
    g2+='<text class="tick" x="'+(L-6)+'" y="'+(py(0)+0).toFixed(1)+'" text-anchor="end">0</text>';
    var xlab = al()==="en"?"growth rate g":(al()==="nl"?"groeivoet g":"taux de croissance g");
    var ylab = al()==="en"?"price P₀":(al()==="nl"?"prijs P₀":"prix P₀");
    g2+='<text class="lab" x="'+(L+pw/2)+'" y="'+(H-3)+'" text-anchor="middle">'+xlab+'</text>';
    g2+='<text class="lab" x="'+(L-34)+'" y="'+(T+ph/2)+'" text-anchor="middle" transform="rotate(-90 '+(L-34)+' '+(T+ph/2)+')">'+ylab+'</text>';
    svg.innerHTML=g2;
  }

  ["eq-d","eq-r","eq-g"].forEach(function(id){ var e=document.getElementById(id); if(e) e.addEventListener("input", draw); });
  document.querySelectorAll("[data-set-lang]").forEach(function(b){ b.addEventListener("click", function(){ setTimeout(draw,10); }); });
  document.addEventListener("DOMContentLoaded", draw);
  draw();
})();
